module sr_latch (
    input S,
    input R,
    output reg Q,
    output reg Qn
);

always @(S or R) begin
    if (S == 1 && R == 0) begin
        Q = 1;
        Qn = 0;
    end else if (S == 0 && R == 1) begin
        Q = 0;
        Qn = 1;
    end else if (S == 0 && R == 0) begin
        // Maintain previous state
        Q = Q;
        Qn = Qn;
    end else if (S == 1 && R == 1) begin
        // Undefined state, can be a hold or any predefined state
        Q = 1'bx;
        Qn = 1'bx;
    end
end
endmodule

